const body = $input.first().json.body || $input.first().json;

const project = body.project_name || 'Unknown Project';
const customer = body.customer || '';
const reqs = body.requirements_found || 0;
const contradictions = body.contradictions_found || 0;
const highRisk = body.high_risk_count || 0;
const projectId = body.project_id || '';
const filename = body.filename || 'document';

const riskEmoji = highRisk > 5 ? '🔴' : highRisk > 2 ? '🟡' : '🟢';
const contradictionWarning = contradictions > 0 ? `⚠️ ${contradictions} contradiction(s) detected — review before bidding` : '✅ No contradictions detected';

const message = `${riskEmoji} *RFQ Analysis Complete*

*Project:* ${project}${customer ? ' — ' + customer : ''}
*Document:* ${filename}

*Results:*
• ${reqs} requirements extracted
• ${highRisk} high-risk items
• ${contradictionWarning}

<http://localhost:5173/rfq?project=${projectId}|View full analysis →>`;

const emailHtml = `
<h2 style="color:#1a3a5c">RFQ Analysis Complete</h2>
<p><strong>Project:</strong> ${project}${customer ? ' — ' + customer : ''}</p>
<p><strong>Document:</strong> ${filename}</p>
<hr/>
<h3>Results</h3>
<ul>
<li>${reqs} requirements extracted</li>
<li>${highRisk} high-risk items ${riskEmoji}</li>
<li>${contradictionWarning}</li>
</ul>
<p><a href="http://localhost:5173/rfq?project=${projectId}" style="background:#3b82f6;color:white;padding:10px 20px;text-decoration:none;border-radius:6px">View Full Analysis</a></p>
`;

return [{ json: { message, emailHtml, project, reqs, contradictions, highRisk, projectId } }];
